class Solution {
public:
    int minCost(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size(), N = m * n;
        const int INF = 1000000000;
        vector<pair<int, int>> cells;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j) cells.push_back({grid[i][j], i * n + j});
        sort(cells.begin(), cells.end());
        vector<int> dp(N, INF); dp[0] = 0;
        for (int step = 0; step <= k; ++step) {
            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < n; ++j) {
                    int id = i * n + j;
                    if (i > 0 && dp[id - n] != INF) dp[id] = min(dp[id], dp[id - n] + grid[i][j]);
                    if (j > 0 && dp[id - 1] != INF) dp[id] = min(dp[id], dp[id - 1] + grid[i][j]);
                }
            }
            if (step == k) break;
            vector<int> next(N, INF);
            int best = INF;
            for (int t = N - 1; t >= 0;) {
                int p = t;
                while (p >= 0 && cells[p].first == cells[t].first) --p;
                for (int j = p + 1; j <= t; ++j) best = min(best, dp[cells[j].second]);
                for (int j = p + 1; j <= t; ++j) next[cells[j].second] = best;
                t = p;
            }
            dp.swap(next);
        }
        return dp[N - 1];
    }
};
